-- Governed resources have separate tables, indexed relationships and tenant keys.
CREATE TABLE IF NOT EXISTS alarm_governance_template(tenant_id text NOT NULL,id text NOT NULL,version bigint NOT NULL CHECK(version>0),created_by text NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,
 case_id text,round_id text,parent_id text,resource_id text,revision_number integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT '',owner_user_id text NOT NULL DEFAULT '',device_ids text[] NOT NULL DEFAULT '{}',point_key text NOT NULL DEFAULT '',occurred_at bigint NOT NULL DEFAULT 0,corrects_id text,
 body jsonb NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,resource_id,revision_number));
CREATE INDEX IF NOT EXISTS alarm_governance_template_scope_idx ON alarm_governance_template USING gin(device_ids);
CREATE INDEX IF NOT EXISTS alarm_governance_template_list_idx ON alarm_governance_template(tenant_id,status,owner_user_id,updated_at DESC,id);
CREATE INDEX IF NOT EXISTS alarm_governance_template_round_idx ON alarm_governance_template(tenant_id,round_id,occurred_at,id);
CREATE TABLE IF NOT EXISTS alarm_governance_scene_preset(tenant_id text NOT NULL,id text NOT NULL,version bigint NOT NULL CHECK(version>0),created_by text NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,
 case_id text,round_id text,parent_id text,resource_id text,revision_number integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT '',owner_user_id text NOT NULL DEFAULT '',device_ids text[] NOT NULL DEFAULT '{}',point_key text NOT NULL DEFAULT '',occurred_at bigint NOT NULL DEFAULT 0,corrects_id text,
 body jsonb NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,resource_id,revision_number));
CREATE INDEX IF NOT EXISTS alarm_governance_scene_preset_scope_idx ON alarm_governance_scene_preset USING gin(device_ids);
CREATE INDEX IF NOT EXISTS alarm_governance_scene_preset_list_idx ON alarm_governance_scene_preset(tenant_id,status,owner_user_id,updated_at DESC,id);
CREATE INDEX IF NOT EXISTS alarm_governance_scene_preset_round_idx ON alarm_governance_scene_preset(tenant_id,round_id,occurred_at,id);
