 case_id text,round_id text,parent_id text,resource_id text,revision_number integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT '',owner_user_id text NOT NULL DEFAULT '',device_ids text[] NOT NULL DEFAULT '{}',point_key text NOT NULL DEFAULT '',occurred_at bigint NOT NULL DEFAULT 0,corrects_id text,
 body jsonb NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,resource_id,revision_number));
CREATE INDEX IF NOT EXISTS alarm_governance_type_profile_scope_idx ON alarm_governance_type_profile USING gin(device_ids);
CREATE INDEX IF NOT EXISTS alarm_governance_type_profile_list_idx ON alarm_governance_type_profile(tenant_id,status,owner_user_id,updated_at DESC,id);
CREATE INDEX IF NOT EXISTS alarm_governance_type_profile_round_idx ON alarm_governance_type_profile(tenant_id,round_id,occurred_at,id);
CREATE TABLE IF NOT EXISTS alarm_governance_case(tenant_id text NOT NULL,id text NOT NULL,version bigint NOT NULL CHECK(version>0),created_by text NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,
 case_id text,round_id text,parent_id text,resource_id text,revision_number integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT '',owner_user_id text NOT NULL DEFAULT '',device_ids text[] NOT NULL DEFAULT '{}',point_key text NOT NULL DEFAULT '',occurred_at bigint NOT NULL DEFAULT 0,corrects_id text,
 body jsonb NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE INDEX IF NOT EXISTS alarm_governance_case_scope_idx ON alarm_governance_case USING gin(device_ids);
CREATE INDEX IF NOT EXISTS alarm_governance_case_list_idx ON alarm_governance_case(tenant_id,status,owner_user_id,updated_at DESC,id);
CREATE INDEX IF NOT EXISTS alarm_governance_case_round_idx ON alarm_governance_case(tenant_id,round_id,occurred_at,id);
CREATE TABLE IF NOT EXISTS alarm_governance_round(tenant_id text NOT NULL,id text NOT NULL,version bigint NOT NULL CHECK(version>0),created_by text NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,
 case_id text,round_id text,parent_id text,resource_id text,revision_number integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT '',owner_user_id text NOT NULL DEFAULT '',device_ids text[] NOT NULL DEFAULT '{}',point_key text NOT NULL DEFAULT '',occurred_at bigint NOT NULL DEFAULT 0,corrects_id text,
 body jsonb NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,case_id) REFERENCES alarm_governance_case(tenant_id,id) DEFERRABLE INITIALLY DEFERRED,UNIQUE(tenant_id,case_id,revision_number));
CREATE INDEX IF NOT EXISTS alarm_governance_round_scope_idx ON alarm_governance_round USING gin(device_ids);
CREATE INDEX IF NOT EXISTS alarm_governance_round_list_idx ON alarm_governance_round(tenant_id,status,owner_user_id,updated_at DESC,id);
CREATE INDEX IF NOT EXISTS alarm_governance_round_round_idx ON alarm_governance_round(tenant_id,round_id,occurred_at,id);
