CREATE INDEX IF NOT EXISTS alarm_governance_verification_correction_idx ON alarm_governance_verification(tenant_id,corrects_id,status) WHERE corrects_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS alarm_governance_verification_link(tenant_id text NOT NULL,id text NOT NULL,version bigint NOT NULL CHECK(version>0),created_by text NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,
 case_id text,round_id text,parent_id text,resource_id text,revision_number integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT '',owner_user_id text NOT NULL DEFAULT '',device_ids text[] NOT NULL DEFAULT '{}',point_key text NOT NULL DEFAULT '',occurred_at bigint NOT NULL DEFAULT 0,corrects_id text,
 body jsonb NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,case_id) REFERENCES alarm_governance_case(tenant_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(tenant_id,round_id) REFERENCES alarm_governance_round(tenant_id,id) DEFERRABLE INITIALLY DEFERRED,verification_id text GENERATED ALWAYS AS (body->>'verificationId') STORED,FOREIGN KEY(tenant_id,verification_id) REFERENCES alarm_governance_verification(tenant_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS alarm_governance_verification_link_scope_idx ON alarm_governance_verification_link USING gin(device_ids);
CREATE INDEX IF NOT EXISTS alarm_governance_verification_link_list_idx ON alarm_governance_verification_link(tenant_id,status,owner_user_id,updated_at DESC,id);
CREATE INDEX IF NOT EXISTS alarm_governance_verification_link_round_idx ON alarm_governance_verification_link(tenant_id,round_id,occurred_at,id);
