CREATE UNIQUE INDEX IF NOT EXISTS alarm_governance_active_round ON alarm_governance_round(tenant_id,case_id) WHERE status='ACTIVE';
CREATE TABLE IF NOT EXISTS alarm_governance_source_version(tenant_id text NOT NULL,dependency_key text NOT NULL,bucket_start bigint NOT NULL,generation bigint NOT NULL DEFAULT 0 CHECK(generation>=0),PRIMARY KEY(tenant_id,dependency_key,bucket_start));
CREATE TABLE IF NOT EXISTS alarm_governance_published_config(tenant_id text NOT NULL,kind text NOT NULL,resource_id text NOT NULL,revision_id text NOT NULL,version bigint NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,kind,resource_id));

-- Every committed resource version remains inspectable after current state advances.
CREATE TABLE IF NOT EXISTS alarm_governance_template_history(tenant_id text NOT NULL,resource_id text NOT NULL,version bigint NOT NULL CHECK(version>0),recorded_at bigint NOT NULL,body jsonb NOT NULL,PRIMARY KEY(tenant_id,resource_id,version),FOREIGN KEY(tenant_id,resource_id) REFERENCES alarm_governance_template(tenant_id,id) DEFERRABLE INITIALLY DEFERRED);
