-- Recoverable private upload attempts are separate from immutable request receipts.
CREATE TABLE IF NOT EXISTS alarm_governance_upload_attempt(tenant_id text NOT NULL,id text NOT NULL,version bigint NOT NULL CHECK(version>0),created_by text NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,
 case_id text,round_id text,parent_id text,resource_id text,revision_number integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT '',owner_user_id text NOT NULL DEFAULT '',device_ids text[] NOT NULL DEFAULT '{}',point_key text NOT NULL DEFAULT '',occurred_at bigint NOT NULL DEFAULT 0,corrects_id text,
 body jsonb NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE INDEX IF NOT EXISTS alarm_governance_upload_attempt_scope_idx ON alarm_governance_upload_attempt USING gin(device_ids);
CREATE INDEX IF NOT EXISTS alarm_governance_upload_attempt_list_idx ON alarm_governance_upload_attempt(tenant_id,status,owner_user_id,updated_at DESC,id);
CREATE INDEX IF NOT EXISTS alarm_governance_upload_attempt_round_idx ON alarm_governance_upload_attempt(tenant_id,round_id,occurred_at,id);

CREATE TABLE IF NOT EXISTS alarm_governance_upload_attempt_history(tenant_id text NOT NULL,resource_id text NOT NULL,version bigint NOT NULL CHECK(version>0),recorded_at bigint NOT NULL,body jsonb NOT NULL,PRIMARY KEY(tenant_id,resource_id,version),FOREIGN KEY(tenant_id,resource_id) REFERENCES alarm_governance_upload_attempt(tenant_id,id) DEFERRABLE INITIALLY DEFERRED);
